const body = $input.first().json.body ?? $input.first().json;

const title = (body.title || 'Rappel').trim();
const description = (body.description || '').trim();
const datetimeRaw = body.reminder_datetime;
const userId = body.user_id || 'default_user';
const timezone = body.timezone || 'Africa/Tunis';
const lang = (body.language || 'fr').toLowerCase();
const callbackUrl = body.callback_url || '';

// 🔒 SECURITY: restrict callback
if (!callbackUrl.startsWith('http://localhost:8000') && !callbackUrl.startsWith('https://yourdomain.com')) {
  throw new Error('Invalid callback_url');
}

const actionId = body.action_id || 'reminder_' + Date.now() + '_' + userId.replace(/[^a-z0-9]/gi, '_');

if (!datetimeRaw) throw new Error('VALIDATION_ERROR: reminder_datetime required');

const reminderMs = Date.parse(datetimeRaw);
if (isNaN(reminderMs)) throw new Error('Invalid datetime: ' + datetimeRaw);
if (reminderMs <= Date.now() + 30000) throw new Error('Datetime must be 30s in future');

const startDate = new Date(reminderMs);
const endDate = new Date(reminderMs + 30 * 60 * 1000);

let localTime;
try {
  localTime = new Intl.DateTimeFormat(lang === 'ar' ? 'ar-TN' : lang === 'en' ? 'en-US' : 'fr-FR', {
    timeZone: timezone, dateStyle: 'full', timeStyle: 'short'
  }).format(startDate);
} catch(e) { localTime = startDate.toISOString(); }

const msgs = {
  fr: { confirm: 'Rappel programme : ' + title + ' le ' + localTime, alert: 'Rappel ! ' + title + '. Il est l heure.' },
  en: { confirm: 'Reminder set: ' + title + ' on ' + localTime, alert: 'Reminder! ' + title + '. It is time.' },
  ar: { confirm: 'تم ضبط التذكير: ' + title + ' في ' + localTime, alert: 'تذكير! ' + title + '. حان الوقت.' }
};

const msg = msgs[lang] || msgs.fr;

return [{ json: {
  title, description,
  reminder_datetime: datetimeRaw,
  reminder_datetime_ms: reminderMs,
  start_iso: startDate.toISOString(),
  end_iso: endDate.toISOString(),
  user_id: userId,
  timezone,
  language: lang,
  callback_url: callbackUrl,
  action_id: actionId,
  confirm_message: msg.confirm,
  tts_text: msg.alert,
  created_at: new Date().toISOString()
}}];

const data = $input.first().json;

function formatICS(d) {
  return d.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';
}

function escapeICS(text) {
  return text
    .replace(/\\/g, '\\\\')
    .replace(/\n/g, '\\n')
    .replace(/,/g, '\\,')
    .replace(/;/g, '\\;');
}

const startDate = new Date(data.reminder_datetime_ms);
const endDate = new Date(data.reminder_datetime_ms + 30 * 60 * 1000);
const now = new Date();

const title = escapeICS(data.title);
const description = escapeICS(data.description || data.title);

const ics = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//GOB AI//EN',
  'BEGIN:VEVENT',
  'UID:' + data.action_id + '@gob',
  'DTSTAMP:' + formatICS(now),
  'DTSTART:' + formatICS(startDate),
  'DTEND:' + formatICS(endDate),
  'SUMMARY:' + title,
  'DESCRIPTION:' + description,
  'BEGIN:VALARM',
  'TRIGGER:-PT10M',
  'ACTION:DISPLAY',
  'DESCRIPTION:Reminder in 10 min',
  'END:VALARM',
  'BEGIN:VALARM',
  'TRIGGER:-PT5M',
  'ACTION:DISPLAY',
  'DESCRIPTION:Reminder in 5 min',
  'END:VALARM',
  'BEGIN:VALARM',
  'TRIGGER:PT0S',
  'ACTION:DISPLAY',
  'DESCRIPTION:NOW',
  'END:VALARM',
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n');

const icsBase64 = Buffer.from(ics).toString('base64');

return [{ json: {
  ...data,
  ics_content: ics,
  ics_base64: icsBase64
}}];

const data = $input.first().json;

const mqttPayload = JSON.stringify({
  type: 'reminder_alert',
  user_id: data.user_id,
  title: data.title,
  action_id: data.action_id,
  fired_at: new Date().toISOString()
});

return [{ json: {
  callback_url: data.callback_url,
  action_id: data.action_id,
  title: data.title,
  tts_text: data.tts_text,
  user_id: data.user_id,
  language: data.language,
  mqtt_topic: 'device/reminder/' + data.user_id,
  mqtt_payload: mqttPayload,
  fired_at: new Date().toISOString()
}}];
